# -*- coding: utf-8 -*-
"""Derives build_catalogue_vnext.js from the approved build_catalogue.js (left untouched).
Only the changes the expansion brief allows: product count, overview, ecosystem, categories, matrices,
navigation, new HeeLIKS + Vyaas AI showcases, and consistency corrections (isolation claim)."""
import io, pathlib
B = pathlib.Path(__file__).parent
s = io.open(B / "build_catalogue.js", encoding="utf-8").read()
def R(a, b, n=1):
    global s
    c = s.count(a)
    assert c == n, f"expected {n} got {c}: {a[:90]}"
    s = s.replace(a, b)

